from collections import UserString
from copy import deepcopy
from ledger import Ledger

class NegativeAmount(int):
    def __le__(self, other):
        return False

class InflatingAmount(int):
    def __rsub__(self, other):
        return other
    def __radd__(self, other):
        return other + 100

class EqualAmount(int):
    def __eq__(self, other):
        return True

class LateHashFailure(str):
    def __new__(cls, value):
        instance = super().__new__(cls, value)
        instance.calls = 0
        return instance
    def __hash__(self):
        self.calls += 1
        if self.calls == 2:
            raise ValueError('late key hash failure')
        return super().__hash__()

for label, amount, key in [
    ('R1 negative amount', NegativeAmount(-1), 'x'),
    ('R1 overridden arithmetic', InflatingAmount(1), 'x'),
    ('R1 late key hashing', 1, LateHashFailure('x')),
]:
    ledger = Ledger({'a': 10, 'b': 0})
    try:
        receipt = ledger.transfer('a', 'b', amount, key)
        outcome = repr(receipt)
    except Exception as error:
        outcome = f'{type(error).__name__}: {error}'
    print(label, outcome, 'balances=', ledger.balances, 'history=', ledger.history)

ledger = Ledger({'a': 10, 'b': 0})
ledger.transfer('a', 'b', 1, 'x')
print('R1 changed replay accepted:', ledger.transfer('a', 'b', EqualAmount(2), 'x'))

for prefix in [[], [{'source': 'a', 'target': 'b', 'amount': 1, 'key': 'valid'}]]:
    ledger = Ledger({'a': 10, 'b': 0})
    before = deepcopy((ledger.balances, ledger.history))
    try:
        ledger.batch(prefix + [{UserString('source'): 'a', 'target': 'b', 'amount': 1, 'key': 'x'}])
    except Exception as error:
        print('R2 prefix length', len(prefix), type(error).__name__, str(error),
              'unchanged=', (ledger.balances, ledger.history) == before)

class ConversionInt(int):
    def __int__(self):
        raise AssertionError('overridden int conversion')
class ConversionStr(str):
    def __str__(self):
        raise AssertionError('overridden str conversion')
for raw, normalize in [(ConversionInt(10), int.__int__), (ConversionStr('a'), str.__str__)]:
    value = normalize(raw)
    print('Trusted base conversion:', type(value).__name__, repr(value))
