from collections import UserString
from copy import deepcopy
from ledger import Ledger

class Amount(int):
    def __int__(self):
        return 999
    def __le__(self, other):
        return False

class Key(str):
    def __hash__(self):
        raise ValueError('subclass hashing is unsafe')

ledger = Ledger({'a': Amount(100), 'b': 0, 'c': 20})
balances, history = ledger.balances, ledger.history
initial = ledger.transfer('a', 'b', Amount(10), Key('initial'))
first = {'source': 'a', 'target': 'b', 'amount': Amount(90), 'key': Key('first')}
second = {'source': 'b', 'target': 'c', 'amount': Amount(100), 'key': Key('second')}
third = {'source': 'c', 'target': 'a', 'amount': Amount(120), 'key': Key('third')}
receipts = ledger.batch([first, first, initial, second, third])
assert balances == {'a': 120, 'b': 0, 'c': 0}
assert sum(balances.values()) == 120
before = deepcopy((balances, history))
assert ledger.batch([first, initial, second, third]) == [receipts[0], initial, receipts[3], receipts[4]]
receipts[0].clear()
assert (balances, history) == before

retry = {'source': 'a', 'target': 'b', 'amount': Amount(30), 'key': Key('retry')}
invalid_operations = [
    {'source': 'a', 'target': 'b', 'amount': Amount(-1), 'key': Key('negative')},
    {UserString('source'): 'a', 'target': 'b', 'amount': 1, 'key': 'malformed'},
    {'source': 'a', 'target': 'b', 'amount': Amount(11), 'key': Key('initial')},
    {'source': 'c', 'target': 'a', 'amount': 1, 'key': 'overdraft'},
]
for operation in invalid_operations:
    try:
        ledger.batch([retry, operation])
    except ValueError:
        pass
    else:
        raise AssertionError('invalid batch succeeded')
    assert (balances, history) == before

ledger.batch([retry, retry])
ledger.transfer('b', 'c', Amount(30), Key('settle'))
assert balances == {'a': 90, 'b': 0, 'c': 30}
assert sum(balances.values()) == 120
assert ledger.balances is balances and ledger.history is history
assert set(history) == {'initial', 'first', 'second', 'third', 'retry', 'settle'}
assert all(type(value) is int for value in balances.values())
assert all(type(key) is str for key in history)
print('PASS: public constructor -> transfer -> atomic batch -> replay -> detached receipt -> four rollback cases -> retry -> settlement.')
print('Final balances:', balances, '; total:', sum(balances.values()), '; history entries:', len(history))
